export const catLabel = (c: PrepCat, lang: string): string => (lang === 'nb' ? CAT_NB : CAT_EN)[c];
const CAT_NB: Record<PrepCat, string> = { water: 'Vann', food: 'Mat', heat: 'Varme', light: 'Lys og strøm', comms: 'Informasjon og kontakt', cooking: 'Matlaging', hygiene: 'Hygiene', health: 'Helse og medisin', money: 'Penger og papirer', pets: 'Kjæledyr', baby: 'Baby', gobag: 'Evakueringssekk' };
const CAT_EN: Record<PrepCat, string> = { water: 'Water', food: 'Food', heat: 'Warmth', light: 'Light and power', comms: 'Information and contact', cooking: 'Cooking', hygiene: 'Hygiene', health: 'Health and medicine', money: 'Money and papers', pets: 'Pets', baby: 'Baby', gobag: 'Go-bag' };
export const itemName = (i: PrepItem, lang: string) => (lang === 'nb' ? i.nb : i.en);
export const itemUnit = (i: PrepItem, lang: string) => (lang === 'nb' ? i.unitNb : i.unitEn);
export const itemTip = (i: PrepItem, lang: string) => (lang === 'nb' ? i.tipNb : i.tipEn);

export type PrepStock = {
  id: string; household_id?: string; key: string | null; name: string; category: string; qty: number; unit: string | null; expires_on: string | null;
  renew_months: number | null; location: string | null; notes: string | null;
};

const persons = (p: PrepProfile) => Math.max(1, p.adults + p.children);
export const WATER_PET_L_PER_DAY = 0.5;

export function applies(i: PrepItem, p: PrepProfile): boolean {
  if (i.only === 'pets') return p.pets > 0;
  if (i.only === 'baby') return p.baby;
  if (i.only === 'woodStove') return p.wood_stove;
  if (i.only === 'iodine') return p.iodine_people > 0;
  return true;
}

/** How many a household should have: DSB's advice scaled by people, days and pets, unless you set your own number. */
export function targetQty(i: PrepItem, p: PrepProfile): number {
  const own = p.overrides[i.key];
  if (own != null && Number.isFinite(own) && own >= 0) return own;
  const n = persons(p);
  switch (i.basis) {
    case 'perPersonPerDay': return Math.ceil(i.rate * n * p.days + (i.key === 'water' ? WATER_PET_L_PER_DAY * p.pets * p.days : 0));
    case 'perPerson': return Math.ceil(i.rate * n);
    case 'perAdult': return Math.ceil(i.rate * Math.max(1, p.adults));
    case 'household': return i.rate;
    case 'perPetPerDay': return Math.ceil(i.rate * p.pets * p.days);
    case 'perIodine': return Math.ceil(i.rate * p.iodine_people);
    case 'perBabyDay': return Math.ceil(i.rate * p.days);
  }
}

export const haveQty = (stock: PrepStock[], key: string): number => Math.round(stock.filter((s) => s.key === key).reduce((a, s) => a + Number(s.qty), 0) * 100) / 100;

export type ItemState = { item: PrepItem; target: number; have: number; missing: number; pct: number; done: boolean };
export function itemStates(p: PrepProfile, stock: PrepStock[]): ItemState[] {
  return PREP_ITEMS.filter((i) => applies(i, p)).map((item) => {
    const target = targetQty(item, p);
    const have = haveQty(stock, item.key);
    const missing = Math.max(0, Math.round((target - have) * 100) / 100);
    const pct = target <= 0 ? 1 : Math.min(1, have / target);
    return { item, target, have, missing, pct, done: missing === 0 };
  });
}

export type Readiness = { days: number; percent: number; byCat: Partial<Record<PrepCat, { pct: number; done: number; total: number }>>; weakest: 'water' | 'food' | 'heat' | null; waterDays: number; mealDays: number; heatDays: number };

/** How long you would manage and how complete the list is. Days are limited by the three things that run out: water, meals and something warm to sleep in. */
export function readiness(p: PrepProfile, stock: PrepStock[]): Readiness {
  const n = persons(p);
  const states = itemStates(p, stock);
  const waterNeedPerDay = 3 * n + WATER_PET_L_PER_DAY * p.pets;
  const waterDays = haveQty(stock, 'water') / waterNeedPerDay;
  const meals = PREP_ITEMS.filter((i) => i.group === 'meals').reduce((a, i) => a + haveQty(stock, i.key), 0);
  const mealDays = meals / (2 * n);
  const bag = states.find((s) => s.item.key === 'sleeping_bag');
  const heatDays = (bag ? bag.pct : 0) * p.days;
  const cap = (d: number) => Math.min(p.days, Math.floor(d * 10) / 10);
  const days = Math.min(cap(waterDays), cap(mealDays), cap(heatDays));
  const counted = states.filter((s) => !s.item.optional);
  const percent = counted.length === 0 ? 0 : Math.round((counted.reduce((a, s) => a + s.pct, 0) / counted.length) * 100);
  const byCat: Readiness['byCat'] = {};
  for (const c of PREP_CATS) {
    const list = counted.filter((s) => s.item.cat === c);
    if (list.length) byCat[c] = { pct: Math.round((list.reduce((a, s) => a + s.pct, 0) / list.length) * 100), done: list.filter((s) => s.done).length, total: list.length };
  }
  const ranked: ['water' | 'food' | 'heat', number][] = [['water', waterDays], ['food', mealDays], ['heat', heatDays]];
  const worst = ranked.sort((a, b) => a[1] - b[1])[0];
  return { days, percent, byCat, weakest: worst[1] < p.days ? worst[0] : null, waterDays: cap(waterDays), mealDays: cap(mealDays), heatDays: cap(heatDays) };
}

export const missingItems = (p: PrepProfile, stock: PrepStock[]): ItemState[] => itemStates(p, stock).filter((s) => s.missing > 0 && !s.item.optional);

// ---- Dates --------------------------------------------------------------------------------------------------------------------------
const pad = (n: number) => String(n).padStart(2, '0');
export const isoOf = (d: Date) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const dayNumber = (iso: string) => Math.floor(Date.UTC(+iso.slice(0, 4), +iso.slice(5, 7) - 1, +iso.slice(8, 10)) / 86_400_000);
export const daysUntil = (date: string, today: string): number => dayNumber(date) - dayNumber(today);

/** A date `months` later; the day is kept, or clamped to the end of a shorter month (31 Aug + 6 months is 28 Feb). */
export function addMonths(iso: string, months: number): string {
  const y = +iso.slice(0, 4), m = +iso.slice(5, 7) - 1, d = +iso.slice(8, 10);
  const total = y * 12 + m + months;
  const ny = Math.floor(total / 12), nm = total % 12;
  const last = new Date(ny, nm + 1, 0).getDate();
  return `${ny}-${pad(nm + 1)}-${pad(Math.min(d, last))}`;
}

/** "03/2027" or "2027-03" as printed on a package ("best before end of month") means the last day of that month. */
export function parseMonthDate(raw: string): string | null {
  const v = raw.trim();
  const m = v.match(/^(\d{1,2})[./-](\d{4})$/) ?? v.match(/^(\d{4})[./-](\d{1,2})$/);
  if (!m) return null;
  const [a, b] = [+m[1], +m[2]];
  const year = a > 31 ? a : b, month = a > 31 ? b : a;
  if (month < 1 || month > 12 || year < 2000 || year > 2200) return null;
  return `${year}-${pad(month)}-${pad(new Date(year, month, 0).getDate())}`;
}

export type ExpiryState = 'none' | 'expired' | 'soon' | 'ok';
export const expiryState = (date: string | null, today: string, leadDays: number): ExpiryState => (!date ? 'none' : daysUntil(date, today) < 0 ? 'expired' : daysUntil(date, today) <= leadDays ? 'soon' : 'ok');

/** Stock that has expired or expires within `within` days, soonest first. */
export function expiringSoon(stock: PrepStock[], today: string, within: number): PrepStock[] {
  return stock.filter((s) => s.expires_on && daysUntil(s.expires_on, today) <= within).sort((a, b) => (a.expires_on as string).localeCompare(b.expires_on as string));
}
export const byExpiry = (stock: PrepStock[]): PrepStock[] => [...stock].sort((a, b) => (a.expires_on ?? '9999-99-99').localeCompare(b.expires_on ?? '9999-99-99') || a.name.localeCompare(b.name, 'nb'));

export type ExpiryDigest = { id: string; at: Date; names: string[]; count: number; expired: number };
/** Notifications: items are grouped by the day their reminder falls (`leadDays` before they expire, 09:00; today's already-passed ones tomorrow), so one
 *  notification can carry many items. At most `max` (the soonest ones) are planned, since iOS allows 64 in all. */
export function expiryDigests(stock: PrepStock[], now: Date, leadDays: number, max = 3): ExpiryDigest[] {
  const today = isoOf(now);
  const tomorrow = isoOf(new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1));
  const groups = new Map<string, PrepStock[]>();
  for (const s of stock) {
    if (!s.expires_on) continue;
    const remind = addDays(s.expires_on, -leadDays);
    const day = remind > today ? remind : tomorrow;
    groups.set(day, [...(groups.get(day) ?? []), s]);
  }
  return [...groups.entries()].sort(([a], [b]) => a.localeCompare(b)).slice(0, max).map(([day, list]) => ({
    id: `prep-${day}`, at: new Date(+day.slice(0, 4), +day.slice(5, 7) - 1, +day.slice(8, 10), 9, 0, 0, 0),
    names: list.sort((a, b) => (a.expires_on as string).localeCompare(b.expires_on as string)).map((s) => s.name), count: list.length, expired: list.filter((s) => (s.expires_on as string) < today).length,
  }));
}
function addDays(iso: string, n: number): string { return isoOf(new Date(+iso.slice(0, 4), +iso.slice(5, 7) - 1, +iso.slice(8, 10) + n)); }

/** A typical best-before date for an item bought today, for the quick chips. */
export const suggestedExpiry = (i: Pick<PrepItem, 'shelfMonths'>, today: string): string | null => (i.shelfMonths ? addMonths(today, i.shelfMonths) : null);

/** Weather that is worth getting ready for in the next three days (storm, a lot of snow, hard frost): the first such day. */
export function stormAhead(days: { date: string; windMs: number; snowCm: number; tMin: number; code: number }[], today: string): { kind: 'storm' | 'wind' | 'snow' | 'frost'; date: string } | null {
  for (const d of days.filter((x) => x.date >= today).slice(0, 4)) {
    if (d.code >= 95 && d.code <= 99) return { kind: 'storm', date: d.date };
    if (d.windMs >= 15) return { kind: 'wind', date: d.date };
    if (d.snowCm >= 10) return { kind: 'snow', date: d.date };
    if (d.tMin <= -15) return { kind: 'frost', date: d.date };
  }
  return null;
}

export const EMERGENCY_NUMBERS: { number: string; nb: string; en: string }[] = [
  { number: '110', nb: 'Brann', en: 'Fire' }, { number: '112', nb: 'Politi', en: 'Police' }, { number: '113', nb: 'Ambulanse (medisinsk nødhjelp)', en: 'Ambulance (medical emergency)' },
  { number: '116117', nb: 'Legevakt', en: 'Out-of-hours doctor' }, { number: '22591300', nb: 'Giftinformasjonen', en: 'Poison information' }, { number: '02800', nb: 'Politiet (ikke nødsituasjon)', en: 'Police (not an emergency)' },
];
export const formatNumber = (n: string): string => (n === '116117' ? '116 117' : n === '22591300' ? '22 59 13 00' : n);

/** The text of the fridge card: emergency numbers, the family plan and what is still missing. Plain text, for printing or sharing. */
export function cardText(lang: string, p: PrepProfile, stock: PrepStock[]): string {
  const nb = lang === 'nb';
  const r = readiness(p, stock);
  const lines = [nb ? 'BEREDSKAPSKORT' : 'PREPAREDNESS CARD', '', nb ? 'Nødnumre' : 'Emergency numbers', ...EMERGENCY_NUMBERS.map((e) => `${formatNumber(e.number)}  ${nb ? e.nb : e.en}`)];
  if (p.meeting_place) lines.push('', `${nb ? 'Møtested' : 'Meeting place'}: ${p.meeting_place}`);
  if (p.outside_contact) lines.push(`${nb ? 'Kontaktperson utenfor området' : 'Contact outside the area'}: ${p.outside_contact}`);
  if (p.notes) lines.push('', p.notes);
  lines.push('', nb ? `Lager: klarer oss ca. ${r.days} av ${p.days} dager (${r.percent} % av listen)` : `Stock: about ${r.days} of ${p.days} days (${r.percent}% of the list)`);
  const miss = missingItems(p, stock);
  if (miss.length) lines.push(nb ? 'Mangler:' : 'Missing:', ...miss.map((m) => `- ${itemName(m.item, lang)}: ${m.missing} ${itemUnit(m.item, lang)}`));
  return lines.join('\n');
}

/** The line a to-do gets for something missing: "Drikkevann: 30 liter". */
export const shoppingLine = (s: ItemState, lang: string): string => `${itemName(s.item, lang)}: ${s.missing} ${itemUnit(s.item, lang)}`;
